const body=$input.first().json.body||$input.first().json;
const data=body.data||body.body?.data||{},info=data.Info||{},key=data.key||{};
const fromMe=data.IsFromMe??info.IsFromMe??key.fromMe;
const instance=String(body.instanceName||body.instance||body.body?.instanceName||'').trim();
const id=String(data.ID||info.ID||info.Id||key.id||'').trim();
const chat=String(info.Chat||data.Chat||key.remoteJid||'');
const message=String(data.Message?.conversation||data.Message?.extendedTextMessage?.text||data.message?.conversation||data.message?.extendedTextMessage?.text||data.caption||'').trim();
const event=String(body.event||'').toLowerCase();
if(!['message','messages.upsert'].includes(event)||fromMe!==false||info.IsGroup===true||/@(g\.us|broadcast|newsletter)$/.test(chat)||!id||!instance||!message||message.length>4000)return [];
const candidates=[info.SenderAlt,info.Sender,data.Sender,key.remoteJid,chat].filter(Boolean).map(String);
const sender=candidates.find(s=>/@s\.whatsapp\.net$/.test(s))||candidates[0]||'';
const phone=sender.split('@')[0].replace(/:\d+$/,'').replace(/[^0-9]/g,'');
if(!/^\d{7,16}$/.test(phone)||/@lid$/.test(sender))return [];
return [{json:{instance_name:instance,message_id:id,user_id:phone,customerPhone:phone,sessionId:phone,message,messageText:message,message_type:'text',source:'whatsapp',pushName:String(info.PushName||data.PushName||data.pushName||'Customer').slice(0,80),timestamp:new Date().toISOString(),instanceToken:String(body.instanceToken||body.instance_token||'')}}];

const incoming=$input.first().json;
const name=String(incoming.instance_name||'').trim();
if(!name)return [];
const {Client}=require('pg');
const client=new Client({connectionString:"postgresql://gateway_readonly:gateway_secure_readonly_2026@host.docker.internal:5432"+'/platform_db',connectionTimeoutMillis:5000,
  statement_timeout:5000,query_timeout:6000,options:'-c default_transaction_read_only=on'});
try{
 await client.connect();
 const result=await client.query(`SELECT b.id AS business_id,b.business_code,b.name AS business_name,m.target_db_name
 FROM public.platform_whatsapp_instances i JOIN public.platform_businesses b ON b.business_code=i.business_code
 JOIN public.platform_database_mappings m ON m.business_code=b.business_code
 WHERE i.instance_name=$1 AND b.status='ACTIVE'`,[name]);
 if(result.rows.length!==1)return [];
 const row=result.rows[0];
 if(!['BISE_EDU','POS_RETAIL','HOSP_HEALTH'].includes(row.business_code))return [];
 return [{json:{...incoming,...row,session_id:row.business_code+':'+name+':'+incoming.user_id}}];
}finally{await client.end().catch(()=>{})}

const incoming=$input.first().json;
if(!incoming.instance_name||!incoming.message_id||!incoming.session_id)return [];
const Redis=require('ioredis');
const redis=new Redis({host:'evolution-redis',port:6379,lazyConnect:true,connectTimeout:4000,maxRetriesPerRequest:0,retryStrategy:()=>null,enableOfflineQueue:false});
redis.on('error',()=>{});
try{
 await redis.connect();
 const key='wa:dedup:v2:'+encodeURIComponent(incoming.instance_name)+':'+encodeURIComponent(incoming.message_id);
 const accepted=await redis.set(key,'accepted','EX',86400,'NX');
 if(accepted!=='OK')return [];
 return [{json:{...incoming,redis_transient_state:{storage:'Redis',dedup_claimed:true,ttl_seconds:86400}}}];
}finally{redis.disconnect()}

const inputJson = $input.first()?.json || {};
const userQuery = String(inputJson.query || inputJson.userQuery || inputJson.messageText || '').trim();

// 1. Resolve Trusted Session Context
const incoming = ($('PostgreSQL Persistent Conversation Store').first() || $('Message Normalizer').first() || $json)?.json || {};
const trustedBusinessCode = incoming.business_code || 'POS_RETAIL';
const allowedTools = incoming.allowed_tools || ['search_knowledge_base', 'sync_crm'];

if (!allowedTools.includes('search_knowledge_base')) {
  return JSON.stringify({
    status: 'SECURITY_POLICY_DENIED',
    error_code: 'POLICY_UNAUTHORIZED_TOOL',
    tool: 'search_knowledge_base',
    tenant: trustedBusinessCode,
    message: `[POLICY GATE DENIAL] Tool 'search_knowledge_base' is NOT authorized for tenant '${trustedBusinessCode}'.`
  });
}

// 2. Attempt Live FAISS Vector Store Query via HTTP microservice
try {
  const axios = require('/usr/local/lib/node_modules/n8n/node_modules/axios');
  const faissRes = await axios.post('http://host.docker.internal:8000/search', {
    query: userQuery,
    namespace: incoming.faiss_index_namespace || 'pos_collection',
    top_k: 3
  }, { timeout: 2000 });
  if (faissRes.data && Array.isArray(faissRes.data.results) && faissRes.data.results.length > 0) {
    return faissRes.data.results.map((r, i) => `[FAISS Semantic Citation ${i + 1} | Score: ${r.score}]:\n${r.text}`).join('\n\n');
  }
} catch(e) {}

// 3. Structured Fallback Domain Knowledge Base
const KNOWLEDGE_BASE = {
  'POS_RETAIL': [
    { title: 'POS Billing & Hardware Guide', text: 'GlimsTech POS Retail Automation offers 2D Omnidirectional Barcode Scanners (PKR 35,000) and Thermal 80mm Auto-Cut Printers (PKR 19,500) with 1-year warranty and same-day delivery in Lahore.' },
    { title: 'POS Software License', text: 'POS Retail software includes multi-terminal inventory tracking, barcode printing, sales reports, and offline sync.' }
  ],
  'BISE_EDU': [
    { title: 'BISE Examination Rules & Gazette', text: 'BISE Board Examination Portal allows students to verify Matric & Intermediate annual exam results using 6-digit Roll Numbers. Official gazette records are verified against Board database.' },
    { title: 'BISE Re-checking Policy', text: 'Students can apply for paper re-checking within 15 days of result declaration via official BISE portal.' }
  ],
  'HOSP_HEALTH': [
    { title: 'City Hospital OPD Clinic Directory', text: 'City Healthcare Hospital OPD operates Monday to Saturday from 09:00 AM to 02:00 PM. Cardiology consultations by Dr. Tariq Mahmood (Fee: PKR 2500).' },
    { title: 'Emergency Services', text: '24/7 Emergency Wing and Trauma Center available. For acute life-threatening emergencies, call Rescue 1122.' }
  ]
};

const domainDocs = KNOWLEDGE_BASE[trustedBusinessCode] || KNOWLEDGE_BASE['POS_RETAIL'];
const filtered = domainDocs.filter(doc => 
  doc.title.toLowerCase().includes(userQuery.toLowerCase()) || 
  doc.text.toLowerCase().includes(userQuery.toLowerCase()) ||
  userQuery === ''
);
const results = filtered.length > 0 ? filtered : domainDocs;
return results.map((r, i) => `[Verified Knowledge Citation ${i + 1} | Doc: "${r.title}" | Scope: ${trustedBusinessCode}]:\n${r.text}`).join('\n\n');

