      `INSERT INTO appointments (event_id, customer_phone, push_name, booking_date, booking_time, status, summary)
       VALUES ($1, $2, $3, $4, $5, $6, $7)
       ON CONFLICT (event_id) DO NOTHING;`,
      [eventId, customerPhone, pushName, date, time, 'SCHEDULED', summary]
    );
    await client.end();
    sqlPersisted = true;
  } catch(dbErr) {}

  return JSON.stringify({
