    tenant: businessCode,
    summary: summary,
    description: `Patient: ${pushName} | Phone: ${customerPhone} | DB Persisted: ${sqlPersisted}`
  });
}

return JSON.stringify({ status: 'SUCCESS', message: `Calendar slot processed for ${date} at ${time}` });

